```sql
SELECT doorstep.mart_metro_year AS metro, turnaround.mart_airport_day AS airport, (turnaround.export_mart_inherited_month.flown BIGINT) AS flown FROM doorstep JOIN turnaround ON doorstep.mart_metro_year = turnaround.mart_airport_day;
```

```sql
SELECT Flights flown FROM turnaround.export_mart_inherited_month WHERE carrier = '9E' AND year = 2019;
```
